body:
A potential workaround in v4.5.1 is by using a GDShader to manually set the world tangent and world binormal to consistent values. Note that this will only really work for horizontal surfaces.

`
varying vec3 custom_tangent;
varying vec3 custom_binormal;

void vertex() {
vec3 world_normal = normalize((MODEL_MATRIX * vec4(NORMAL, 0.0)).xyz);

vec3 world_tangent = vec3(1.0, 0.0, 0.0);
vec3 world_binormal = vec3(0.0, 0.0, 1.0);

if (world_normal.y < 0.0) {
world_binormal = -world_binormal;
}

custom_tangent = normalize((VIEW_MATRIX * vec4(world_tangent, 0.0)).xyz);
custom_binormal = normalize((VIEW_MATRIX * vec4(world_binormal, 0.0)).xyz);
}
`

Then in the normal calculation, use the custom tangent and binormal

`
vec3 nm = texture(normal_texture, UV).rgb * 2.0 - 1.0;
nm.xy *= normal_strength;
nm = normalize(nm);

NORMAL = normalize(NORMAL + custom_tangent * nm.x + custom_binormal * nm.y);
`
